const $=i=>document.getElementById(i),enc=new TextEncoder,dec=new TextDecoder;
const b64=b=>{const u=new Uint8Array(b);let r="";for(let i=0;i<u.length;i+=8192)r+=String.fromCharCode.apply(null,u.subarray(i,i+8192));return btoa(r)},ub=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
let me,you,db,key,pc,ls,cid=0,cstate='idle',rec,priv,msgs=[],sel="mansa",peerLoc=null,sharing=false,wid=null;
const hash=async s=>[...new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(s)))].map(x=>x.toString(16).padStart(2,"0")).join("");
function drawWho(){$("who").innerHTML="";for(const k in U){const b=document.createElement("button");b.className=k==sel?"on":"";b.innerHTML='<img class="av" src="'+U[k].img+'"><b>'+U[k].n+'</b>';b.onclick=()=>{sel=k;drawWho()};$("who").append(b)}}
drawWho();
$("go").onclick=async()=>{try{Notification.requestPermission()}catch(e){}const p=$("pw").value.toLowerCase().replace(/\s+/g,"");if(await hash(p)!==U[sel].h){$("err").textContent="Wrong password";return}
me=sel;you=me=="mansa"?"vaibhav":"mansa";$("login").style.display="none";$("app").style.display="flex";$("pav").src=U[you].img;$("pn").textContent=U[you].n;start()};
