async function start(){let cl=window.claude&&await claude.use("db").catch(()=>null);db=cl;
 if(!db){$("bar").textContent="⚠️ Offline demo: open the published link while signed in to chat live.";}
 // keypair per device
 let jw=null;try{jw=JSON.parse(localStorage.getItem("k_"+me))}catch(e){}
 let pub;
 if(jw){priv=await crypto.subtle.importKey("jwk",jw.priv,{name:"ECDH",namedCurve:"P-256"},false,["deriveKey"]);pub=jw.pub}
 else{const kp=await crypto.subtle.generateKey({name:"ECDH",namedCurve:"P-256"},true,["deriveKey"]);priv=kp.privateKey;pub=await crypto.subtle.exportKey("jwk",kp.publicKey);
  try{localStorage.setItem("k_"+me,JSON.stringify({priv:await crypto.subtle.exportKey("jwk",priv),pub}))}catch(e){}
  priv=await crypto.subtle.importKey("jwk",JSON.parse(JSON.stringify(await crypto.subtle.exportKey("jwk",kp.privateKey))),{name:"ECDH",namedCurve:"P-256"},false,["deriveKey"])}
 if(!db){key=await crypto.subtle.generateKey({name:"AES-GCM",length:256},false,["encrypt","decrypt"]);$("ps").textContent="🔒 local only";return}
 await db.doc("keys/"+me).set({pub:JSON.stringify(pub)});
 db.collection("keys").onSnapshot(async s=>{const d=s.docs.find(x=>x.id==you);if(!d)return;const o=d.data?d.data():d;
  const pk=await crypto.subtle.importKey("jwk",JSON.parse(o.pub),{name:"ECDH",namedCurve:"P-256"},false,[]);
  key=await crypto.subtle.deriveKey({name:"ECDH",public:pk},priv,{name:"AES-GCM",length:256},false,["encrypt","decrypt"]);
  $("ps").textContent="🔒 end-to-end encrypted";render()},e=>$("bar").textContent="Connection issue");
 db.collection("msgs").orderBy("t").onSnapshot(s=>{const arr=s.docs.map(d=>d.data?d.data():d);for(const m of arr){const id=m.t+m.from;if(!seen.has(id)){seen.add(id);if(!first&&m.from==you)alertMe("💬 New message from "+U[you].n,1)}}first=false;msgs=arr;render()});
 db.collection("call").onSnapshot(s=>{const d=s.docs.find(x=>x.id==you);if(d)sig(d.data?d.data():d)});
 db.collection("loc").onSnapshot(async s=>{const d=s.docs.find(x=>x.id==you);if(!d||!key)return;const o=d.data?d.data():d;if(o.off){peerLoc=null;return bar()}
  try{peerLoc=JSON.parse(await de(o))}catch(e){}bar()});}
async function en(txt){const iv=crypto.getRandomValues(new Uint8Array(12));return{iv:b64(iv),ct:b64(await crypto.subtle.encrypt({name:"AES-GCM",iv},key,enc.encode(txt)))}}
async function de(o){return dec.decode(await crypto.subtle.decrypt({name:"AES-GCM",iv:ub(o.iv)},key,ub(o.ct)))}
async function send(obj){if(!key){$("ps").textContent="⏳ waiting for "+U[you].n+" to open the app once";return}
 const e=await en(JSON.stringify(obj)),t=Date.now();if(!db){msgs.push({from:me,t,...e});return render()}
 await db.collection("msgs").doc(t+"_"+me).set({from:me,t,...e})}
$("f").onsubmit=e=>{e.preventDefault();const v=$("in").value.trim();if(!v)return;$("in").value="";send({x:v})};
let seq=0;async function render(){const c=++seq,h=[];
 for(const m of msgs){let o;try{o=key?JSON.parse(await de(m)):null}catch(e){}
  const tm=new Date(m.t).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"});
  const okb=o&&o.v&&/^[A-Za-z0-9+\/=]+$/.test(o.v),mt=o&&/^audio\/[a-z0-9]+$/.test(o.mt||'')?o.mt:'audio/webm';
  h.push(!o?'<div class="m '+(m.from==me?"me":"")+'">🔒 <i>can\'t decrypt on this device</i></div>':okb?'<div class="m '+(m.from==me?"me":"")+'">🎤 <audio controls preload="metadata" src="data:'+mt+';base64,'+o.v+'"></audio><small>'+(o.d||'')+'s · '+tm+'</small></div>':Number.isInteger(o.gi)&&GIFS[o.gi]?'<div class="m st '+(m.from==me?"me":"")+'"><img src="'+GIFS[o.gi]+'" height="104" alt="GIF"></div>':o.s?'<div class="m st '+(m.from==me?"me":"")+'"><span class="a-'+o.a+'">'+o.s+'</span></div>':'<div class="m '+(m.from==me?"me":"")+'"></div>');
  if(o&&!o.s&&!o.v&&o.gi==null){const d=document.createElement("div");d.textContent=o.x;h[h.length-1]=h[h.length-1].replace("</div>",d.innerHTML+"<small>"+tm+"</small></div>")}}
 if(c!=seq)return;const el=$("msgs"),nb=el.scrollTop+el.clientHeight>el.scrollHeight-80;el.innerHTML=h.join("");if(nb)el.scrollTop=el.scrollHeight}
function tray(mode){const t=$("tray");if(t.dataset.m==mode&&t.style.display=="block"){t.style.display="none";return}t.dataset.m=mode;t.style.display="block";t.innerHTML="";
 if(mode=="t"){const g=document.createElement("div");g.className="grid";const mk=(l,bg,f)=>{const b=document.createElement("button");b.style.cssText="width:25%;font-size:12px";b.innerHTML='<div style="height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:'+bg+'">'+(bg=="var(--bg)"?"•":"")+'</div>'+l;b.onclick=f;g.append(b)};
 for(const k in TH)mk(k,TH[k],()=>setTh(k));mk("🌗 Dark/Light","var(--bg)",()=>{const r=document.documentElement;r.dataset.theme=r.dataset.theme=="dark"?"light":"dark"});mk("🔗 Copy link","var(--bg)",()=>{navigator.clipboard.writeText(location.href).then(()=>$("bar").textContent="Link copied ✔",()=>$("bar").textContent=location.href)});t.append(g);return}
 if(mode=="g"){const g=document.createElement("div");g.className="grid big";for(let i=0;i<GIFS.length;i++){const b=document.createElement("button");b.innerHTML='<img src="'+GIFS[i]+'" style="width:100%">';b.onclick=()=>{send({gi:i});t.style.display="none"};g.append(b)}for(const[s,a]of ST){const b=document.createElement("button");b.innerHTML='<span class="st"><span class="a-'+a+'">'+s+'</span></span>';b.onclick=()=>{send({s,a});t.style.display="none"};g.append(b)}t.append(g);return}
 const tabs=document.createElement("div");tabs.className="tabs";const g=document.createElement("div");g.className="grid";
 const show=k=>{g.innerHTML="";[...tabs.children].forEach(b=>b.className=b.dataset.k==k?"on":"");for(const ch of EM[k].match(/\p{Extended_Pictographic}\uFE0F?(\u200D\p{Extended_Pictographic}\uFE0F?)*/gu)||[]){const b=document.createElement("button");b.textContent=ch;b.onclick=()=>{$("in").value+=ch;$("in").focus()};g.append(b)}};
 for(const k in EM){const b=document.createElement("button");b.textContent=k;b.dataset.k=k;b.onclick=()=>show(k);tabs.append(b)}t.append(tabs,g);show("😀")}
$("eb").onclick=()=>tray("e");$("gb").onclick=()=>tray("g");
function bar(){if(db)$("bar").innerHTML=peerLoc?'📍 '+U[you].n+' is sharing location · updated '+new Date(peerLoc.t).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})+' · <a target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat='+(+peerLoc.la)+'&mlon='+(+peerLoc.lo)+'#map=16/'+(+peerLoc.la)+'/'+(+peerLoc.lo)+'">Open map</a>':sharing?"📍 You are sharing your location (tap 📍 to stop)":"Location sharing is off for both of you"}
$("locb").onclick=async()=>{if(!db||!key)return;
 if(sharing){navigator.geolocation.clearWatch(wid);sharing=false;$("locb").style.opacity=1;await db.doc("loc/"+me).set({off:true});return bar()}
 if(!navigator.geolocation){$("bar").textContent="Location not available here";return}
 sharing=true;$("locb").style.opacity=.5;let last=0;
 wid=navigator.geolocation.watchPosition(async p=>{if(Date.now()-last<15000)return;last=Date.now();const e=await en(JSON.stringify({la:p.coords.latitude,lo:p.coords.longitude,t:Date.now()}));db.doc("loc/"+me).set(e)},()=>{sharing=false;$("locb").style.opacity=1;$("bar").textContent="Location permission denied"},{enableHighAccuracy:true});bar()};

// ---- voice notes
$("mb").onclick=async()=>{if(rec){rec.stop();return}
 if(!key){$("ps").textContent="⏳ waiting for "+U[you].n+" to open the app once";return}
 try{const st=await navigator.mediaDevices.getUserMedia({audio:true});const ch=[];let t0=Date.now(),go=true;
  const mime=["audio/webm;codecs=opus","audio/mp4"].find(x=>window.MediaRecorder&&MediaRecorder.isTypeSupported(x));
  rec=new MediaRecorder(st,mime?{mimeType:mime,audioBitsPerSecond:20000}:{audioBitsPerSecond:20000});
  rec.ondataavailable=e=>e.data.size&&ch.push(e.data);
  const tm=setInterval(()=>{const n=Math.round((Date.now()-t0)/1000);$("mb").innerHTML='<span class="rec">⏹ '+n+'s</span>';if(n>=30)rec.stop()},500);
  rec.onstop=async()=>{clearInterval(tm);st.getTracks().forEach(t=>t.stop());const type=(rec.mimeType||"audio/webm").split(";")[0],d=Math.round((Date.now()-t0)/1000);rec=null;$("mb").textContent="🎤";
   const buf=await new Blob(ch,{type}).arrayBuffer();if(buf.byteLength>90000){$("bar").textContent="Voice note too long (max 30s)";return}if(d>0)send({v:b64(buf),mt:type,d})};
  rec.start()}catch(e){rec=null;$("bar").textContent="Microphone not available here (permission blocked)"}};
// ---- video call (WebRTC, signalling encrypted with the shared key)
const cbtn=(t,c,f)=>{const b=document.createElement("button");b.textContent=t;b.className=c||"";b.onclick=f;return b};
const cui=(msg,btns)=>{$("call").style.display="flex";$("cs").textContent=msg;$("cb").replaceChildren(...btns)};
async function put(o){if(db&&key)await db.doc("call/"+me).set(await en(JSON.stringify({...o,t:Date.now()})))}
function mk(){pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});ls.getTracks().forEach(t=>pc.addTrack(t,ls));
 pc.ontrack=e=>{$("rv").srcObject=e.streams[0];$("cs").textContent=""};pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState))end(true)}}
const gather=()=>new Promise(r=>{if(pc.iceGatheringState=="complete")return r();pc.onicegatheringstatechange=()=>pc.iceGatheringState=="complete"&&r();setTimeout(r,4000)});
async function media(){ls=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});$("lv").srcObject=ls}
function ctl(){let m=0,v=0;cui("",[cbtn("🎙️","",e=>{m=!m;ls.getAudioTracks().forEach(t=>t.enabled=!m);e.target.style.opacity=m?.4:1}),cbtn("📵","red",()=>end()),cbtn("📷","",e=>{v=!v;ls.getVideoTracks().forEach(t=>t.enabled=!v);e.target.style.opacity=v?.4:1})])}
$("vcb").onclick=async()=>{if(!db||!key){$("bar").textContent="Open the live link and wait for both keys first";return}if(cstate!="idle")return;
 try{await media()}catch(e){$("bar").textContent="Camera/mic blocked here. Allow access or open in a full browser tab.";return}
 cstate="out";cid=Date.now();mk();cui("Calling "+U[you].n+"…",[cbtn("📵","red",()=>end())]);
 await pc.setLocalDescription(await pc.createOffer());await gather();put({k:"offer",cid,sdp:pc.localDescription.sdp})};
async function sig(o){if(!key)return;let p;try{p=JSON.parse(await de(o))}catch(e){return}if(Date.now()-p.t>90000)return;
 if(p.k=="offer"&&cstate=="idle"){cstate="in";cid=p.cid;alertMe("📞 "+U[you].n+" is calling",0);cui("📞 "+U[you].n+" is calling…",[cbtn("✖","red",()=>{put({k:"bye",cid});end(true)}),cbtn("✔","grn",async()=>{
   try{await media()}catch(e){put({k:"bye",cid});end(true);$("bar").textContent="Camera/mic blocked here";return}
   mk();await pc.setRemoteDescription({type:"offer",sdp:p.sdp});await pc.setLocalDescription(await pc.createAnswer());await gather();await put({k:"answer",cid,sdp:pc.localDescription.sdp});cstate="live";ctl()})])}
 else if(p.k=="answer"&&cstate=="out"&&p.cid==cid&&pc.signalingState=="have-local-offer"){await pc.setRemoteDescription({type:"answer",sdp:p.sdp});cstate="live";ctl()}
 else if(p.k=="bye"&&p.cid==cid&&cstate!="idle")end(true)}
function end(quiet){if(!quiet)put({k:"bye",cid});try{pc&&pc.close()}catch(e){}ls&&ls.getTracks().forEach(t=>t.stop());pc=ls=null;cstate="idle";$("rv").srcObject=null;$("call").style.display="none"}

// ---- themes
const TH={Violet:"#6c4df6",Ocean:"#0a84ff",Sunset:"#f5663d",Forest:"#2f9e66",Rose:"#e5487f",Teal:"#0fa3b1",Gold:"#c98a00",Slate:"#4b5575"};
function setTh(k){document.documentElement.style.setProperty("--me",TH[k]);try{localStorage.setItem("th",k)}catch(e){}}
try{const k=localStorage.getItem("th");if(TH[k])setTh(k)}catch(e){}
// ---- notifications, unread red dot
let unread=0,first=true;const seen=new Set();
const near=()=>{const e=$("msgs");return e.scrollTop+e.clientHeight>e.scrollHeight-80};
function beep(){try{const c=new (window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.setValueAtTime(.15,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.3);o.start();o.stop(c.currentTime+.3)}catch(e){}}
function upd(){const p=$("pill");p.style.display=unread?"block":"none";p.textContent="↓ "+unread;document.title=(unread?"("+unread+") ":"")+"21May";
 try{unread?navigator.setAppBadge&&navigator.setAppBadge(unread):navigator.clearAppBadge&&navigator.clearAppBadge()}catch(e){}
 const c=document.createElement("canvas");c.width=c.height=64;const x=c.getContext("2d");x.fillStyle=getComputedStyle(document.documentElement).getPropertyValue("--me")||"#6c4df6";x.beginPath();x.arc(32,32,30,0,7);x.fill();x.fillStyle="#fff";x.font="bold 34px sans-serif";x.textAlign="center";x.fillText("21",32,44);
 if(unread){x.fillStyle="#e5484d";x.beginPath();x.arc(50,14,13,0,7);x.fill()}
 let l=document.querySelector("link[rel=icon]");if(!l){l=document.createElement("link");l.rel="icon";document.head.append(l)}l.href=c.toDataURL()}
function alertMe(txt,count){if(count&&!document.hidden&&near())return;if(count){unread++;upd()}
 if(document.hidden||!count){beep();try{if(Notification.permission=="granted")new Notification("21May",{body:txt})}catch(e){}}}
const clr=()=>{if(unread&&!document.hidden&&near()){unread=0;upd()}};
$("msgs").addEventListener("scroll",clr);document.addEventListener("visibilitychange",clr);window.addEventListener("focus",clr);
$("pill").onclick=()=>{const e=$("msgs");e.scrollTop=e.scrollHeight;unread=0;upd()};
